function siz {
    Write-Host "=== KEY DISK SPACE USAGE ===" -ForegroundColor Cyan
    Write-Host ""
    Write-Host "DRIVES:" -ForegroundColor Yellow
    [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -eq 'Fixed' -and $_.IsReady } | Sort-Object Name | ForEach-Object {
        $total = [math]::Round($_.TotalSize / 1GB, 2)
        $free  = [math]::Round($_.TotalFreeSpace / 1GB, 2)
        $used  = [math]::Round(($_.TotalSize - $_.TotalFreeSpace) / 1GB, 2)
        $pct   = if ($total -gt 0) { [math]::Round(($used / $total) * 100, 1) } else { 0 }
        $drive = $_.Name.TrimEnd('\')
        Write-Host ("{0} {1:N2}GB total, {2:N2}GB used, {3:N2}GB free ({4:N1}%)" -f $drive, $total, $used, $free, $pct)
    }
    Write-Host ""
}

